from decimal import Decimal

def parse_number(text: str) -> Decimal:
    if not isinstance(text, str):
        raise ValueError('invalid number')
    stripped = text.strip(' ' + chr(9) + chr(160))
    if not stripped:
        raise ValueError('invalid number')
    s = stripped
    negative = False
    if '(' in s or ')' in s:
        if len(s) < 2 or s[0] != '(' or s[-1] != ')':
            raise ValueError('invalid number')
        negative = True
        s = s[1:-1].strip(' ' + chr(9) + chr(160))
        if not s:
            raise ValueError('invalid number')
        if s[0] in '+-':
            raise ValueError('invalid number')
    s = s.replace(' ', '').replace(chr(160), '')
    if not s:
        raise ValueError('invalid number')
    if negative:
        if '+' in s or '-' in s:
            raise ValueError('invalid number')
    else:
        if s[0] in '+-':
            negative = s[0] == '-'
            s = s[1:]
            if not s:
                raise ValueError('invalid number')
    if any(ch not in '0123456789.,' for ch in s):
        raise ValueError('invalid number')
    if not any(ch in '0123456789' for ch in s):
        raise ValueError('invalid number')
    has_dot = '.' in s
    has_comma = ',' in s
    decimal_part = None
    integer_digits = ''
    if has_dot and has_comma:
        dec_index = s.rfind('.')
        comma_index = s.rfind(',')
        if comma_index > dec_index:
            dec_index = comma_index
        dec_sep = s[dec_index]
        thou_sep = ',' if dec_sep == '.' else '.'
        int_part = s[:dec_index]
        dec_part = s[dec_index + 1:]
        if not int_part or not dec_part:
            raise ValueError('invalid number')
        if dec_sep in int_part:
            raise ValueError('invalid number')
        groups = int_part.split(thou_sep)
        if len(groups[0]) < 1 or len(groups[0]) > 3:
            raise ValueError('invalid number')
        for group in groups[1:]:
            if len(group) != 3:
                raise ValueError('invalid number')
        integer_digits = ''.join(groups)
        decimal_part = dec_part
    elif has_comma:
        if s.count(',') > 1:
            groups = s.split(',')
            if len(groups[0]) < 1 or len(groups[0]) > 3:
                raise ValueError('invalid number')
            for group in groups[1:]:
                if len(group) != 3:
                    raise ValueError('invalid number')
            integer_digits = ''.join(groups)
        else:
            int_part, dec_part = s.split(',')
            if not int_part or not dec_part:
                raise ValueError('invalid number')
            integer_digits = int_part
            decimal_part = dec_part
    elif has_dot:
        if s.count('.') > 1:
            groups = s.split('.')
            if len(groups[0]) < 1 or len(groups[0]) > 3:
                raise ValueError('invalid number')
            for group in groups[1:]:
                if len(group) != 3:
                    raise ValueError('invalid number')
            integer_digits = ''.join(groups)
        else:
            int_part, dec_part = s.split('.')
            if not int_part or not dec_part:
                raise ValueError('invalid number')
            integer_digits = int_part
            decimal_part = dec_part
    else:
        integer_digits = s
    if not integer_digits:
        raise ValueError('invalid number')
    if decimal_part is not None and not decimal_part:
        raise ValueError('invalid number')
    result_text = integer_digits
    if decimal_part is not None:
        result_text = integer_digits + '.' + decimal_part
    if negative:
        result_text = '-' + result_text
    return Decimal(result_text)
